interface TripCardProps {
    trip: LogisticsTripDto;
    locale: string;
    canManage: boolean;
    isBusy: boolean;
    t: Translate;
    compact?: boolean;
    onEdit: (trip: LogisticsTripDto) => void;
    onDelete: (tripId: number) => void;
    onChangeStatus: (tripId: number, status: LogisticsTripStatus) => void;
}

const TripCard = ({
    trip,
    locale,
    canManage,
    isBusy,
    t,
    compact,
    onEdit,
    onDelete,
    onChangeStatus,
}: TripCardProps) => {
    const nextStatus = nextStatusByStatus[trip.status];
    const tone = statusTone[trip.status];
    const start = trip.calendarEvent.startUtc;
    const end = trip.calendarEvent.endUtc;
    const scheduleText = `${formatDateTime(start, locale)}${end ? ` - ${formatTime(end, locale)}` : ""}`;

    return (
        <TripCardArticle $compact={compact} $overdue={trip.calendarEvent.isOverdue}>
            <TripCardHeader>
                <div>
                    <TripTitle $compact={compact}>{trip.title}</TripTitle>
                    <TripMeta>
                        {t("Order #{id}", {id: trip.orderId})} - {scheduleText}
                    </TripMeta>
                </div>
                <TripBadges>
                    <TripBadge $background={tone.background} $color={tone.color}>
                        {getTripStatusLabel(trip, t)}
                    </TripBadge>
                    <TripBadge $background="var(--color-surface-soft)" $color="var(--color-muted)">
                        {getTripTypeLabel(trip, t)}
                    </TripBadge>
                </TripBadges>
            </TripCardHeader>

            {!compact && (
                <TripDetailsGrid>
                    <TripDetail>
                        <TripDetailLabel>{t("Crew")}</TripDetailLabel>
                        <TripDetailValue>
                            {trip.assignedCrew?.name || trip.calendarEvent.assignedCrewName || t("Unassigned")}
                        </TripDetailValue>
                    </TripDetail>
                    <TripDetail>
                        <TripDetailLabel>{t("Customer")}</TripDetailLabel>
                        <TripDetailValue>{trip.customer.name}</TripDetailValue>
                    </TripDetail>
                    <TripDetail>
                        <TripDetailLabel>{t("Phone")}</TripDetailLabel>
                        <TripDetailValue>
                            <a href={`tel:${trip.contactPhone || trip.customer.phone}`}>
                                {trip.contactPhone || trip.customer.phone || "-"}
                            </a>
                        </TripDetailValue>
                    </TripDetail>
                    <TripDetail>
                        <TripDetailLabel>{t("Address")}</TripDetailLabel>
                        <TripDetailValue>{trip.map.address || trip.customer.address || "-"}</TripDetailValue>
                    </TripDetail>
                    <TripDetail>
                        <TripDetailLabel>{t("Order status")}</TripDetailLabel>
                        <TripDetailValue>{trip.orderStatus || "-"}</TripDetailValue>
                    </TripDetail>
                    <TripDetail>
                        <TripDetailLabel>{t("Total")}</TripDetailLabel>
                        <TripDetailValue>{trip.orderFinalSum || trip.orderTotalSum} BYN</TripDetailValue>
                    </TripDetail>
                </TripDetailsGrid>
            )}

            <MapLinks>
                {trip.map.links.googleMapsUrl && (
                    <MapLink href={trip.map.links.googleMapsUrl} target="_blank" rel="noreferrer">
                        <OpenInNewOutlinedIcon fontSize="small"/>
                        Google Maps
                    </MapLink>
                )}
                {trip.map.links.yandexMapsUrl && (
                    <MapLink href={trip.map.links.yandexMapsUrl} target="_blank" rel="noreferrer">
                        <OpenInNewOutlinedIcon fontSize="small"/>
                        Yandex Maps
                    </MapLink>
                )}
            </MapLinks>

            <TripActions>
                {nextStatus !== undefined && (
                    <CoreButton
                        muiType="success"
                        leftIcon={<CheckCircleOutlineIcon/>}
                        text={t(logisticsTripStatusLabels[nextStatus])}
                        disabled={isBusy}
                        onClick={() => onChangeStatus(trip.id, nextStatus)}
                    />
                )}
                {canManage && trip.status !== LogisticsTripStatus.Cancelled && (
                    <CoreButton
                        muiType="error"
                        leftIcon={<DeleteOutlineIcon/>}
                        text={t("Cancel")}
                        disabled={isBusy}
                        onClick={() => onChangeStatus(trip.id, LogisticsTripStatus.Cancelled)}
                    />
                )}
                {canManage && (
                    <>
                        <CoreButton
                            muiType="info"
                            leftIcon={<EditOutlinedIcon/>}
                            text={t("Edit")}
                            disabled={isBusy}
                            onClick={() => onEdit(trip)}
                        />
                        <CoreButton
                            muiType="error"
                            leftIcon={<DeleteOutlineIcon/>}
                            text={t("Delete")}
                            disabled={isBusy}
                            onClick={() => onDelete(trip.id)}
                        />
                    </>
                )}
            </TripActions>
        </TripCardArticle>
    );
};

