export enum LogisticsTripType {
    Installation = 0,
    Delivery = 1,
    Service = 2,
    Repair = 3,
    Pickup = 4,
    Other = 5,
}

export enum LogisticsTripStatus {
    Planned = 0,
    OnTheWay = 1,
    Arrived = 2,
    Completed = 3,
    Cancelled = 4,
}

export interface LogisticsTripParams {
    from?: string;
    to?: string;
    assignedUserId?: number;
    statuses?: string;
    includeCompleted?: boolean;
    searchTerm?: string;
}

export interface UpcomingTripParams {
    assignedUserId?: number;
    daysAhead?: number;
}

export interface CreateOrEditLogisticsTripDto {
    orderId: number;
    assignedUserId?: number | null;
    type: LogisticsTripType;
    status: LogisticsTripStatus;
    title?: string | null;
    scheduledStartUtc: string;
    scheduledEndUtc?: string | null;
    timeZoneId?: string | null;
    destinationAddress?: string | null;
    latitude?: number | null;
    longitude?: number | null;
    contactName?: string | null;
    contactPhone?: string | null;
    notes?: string | null;
}

export interface LogisticsTripDto {
    id: number;
    firmId: number;
    orderId: number;
    type: LogisticsTripType;
    typeName: string;
    status: LogisticsTripStatus;
    statusName: string;
    title: string;
    calendarEvent: LogisticsCalendarEventDto;
    assignedCrew: LogisticsCrewDto | null;
    customer: LogisticsTripCustomerDto;
    map: LogisticsMapDto;
    orderTotalSum: number;
    orderFinalSum: number;
    orderStatus: string;
    deliveryMethod: string;
    paymentMethod: string;
    source: string;
    mainItemName: string;
    contactName?: string | null;
    contactPhone?: string | null;
    notes?: string | null;
    createdDateUtc: string;
    lastModifiedDateUtc: string;
}

export interface LogisticsCalendarEventDto {
    id: number;
    title: string;
    startUtc: string;
    endUtc?: string | null;
    timeZoneId: string;
    isAllDay: boolean;
    isUpcoming: boolean;
    isOverdue: boolean;
    statusKey: string;
    typeKey: string;
    assignedCrewName?: string | null;
}

export interface LogisticsCrewDto {
    userId: number;
    name: string;
    email: string;
    role: "installer";
}

export interface LogisticsTripCustomerDto {
    name: string;
    address: string;
    phone: string;
}

export interface LogisticsMapDto {
    address: string;
    latitude?: number | null;
    longitude?: number | null;
    hasCoordinates: boolean;
    links: LogisticsMapLinksDto;
}

export interface LogisticsMapLinksDto {
    googleMapsUrl: string;
    yandexMapsUrl: string;
}

export interface LogisticsMapPointDto {
    tripId: number;
    orderId: number;
    title: string;
    status: LogisticsTripStatus;
    statusName: string;
    type: LogisticsTripType;
    typeName: string;
    scheduledStartUtc: string;
    scheduledEndUtc?: string | null;
    assignedCrewName?: string | null;
    customerName: string;
    customerPhone: string;
    address: string;
    latitude?: number | null;
    longitude?: number | null;
    hasCoordinates: boolean;
    links: LogisticsMapLinksDto;
}

export interface InstallationCrewUserDto {
    id: number;
    name: string;
    email: string;
    role: "installer";
}

